import re
from pathlib import Path


class FullStackQualityEngine:
    """Enforce product completeness on projects generated by Autarch."""

    REQUIRED_ROUTES = {
        "/": "apps/web/app/page.tsx",
        "/games": "apps/web/app/games/page.tsx",
        "/login": "apps/web/app/login/page.tsx",
        "/signup": "apps/web/app/signup/page.tsx",
        "/forgot-password": "apps/web/app/forgot-password/page.tsx",
        "/reset-password": "apps/web/app/reset-password/page.tsx",
        "/profile": "apps/web/app/profile/page.tsx",
        "/leaderboard": "apps/web/app/leaderboard/page.tsx",
        "/pricing": "apps/web/app/pricing/page.tsx",
        "/admin": "apps/web/app/admin/page.tsx",
        "/help": "apps/web/app/help/page.tsx",
        "/contact": "apps/web/app/contact/page.tsx",
        "/about": "apps/web/app/about/page.tsx",
        "/privacy": "apps/web/app/privacy/page.tsx",
        "/terms": "apps/web/app/terms/page.tsx",
    }

    def enhance(self, root: Path, brand: str, request: str = ""):
        self._write(root, "apps/web/components/AuthNav.tsx", self._auth_nav(brand))
        self._write(root, "apps/web/app/layout.tsx", self._layout(brand))
        self._write(root, "apps/web/app/forgot-password/page.tsx", self._forgot())
        self._write(root, "apps/web/app/reset-password/page.tsx", self._reset())
        self._write(root, "apps/web/app/help/page.tsx", self._info("Help Center", "Find answers, account guidance and troubleshooting steps.", [("Getting started", "Create an account, choose a game and open its preview."), ("Account support", "Use password recovery if you cannot sign in."), ("Technical support", "Contact the support team with the error and browser details.")]))
        self._write(root, "apps/web/app/contact/page.tsx", self._contact())
        self._write(root, "apps/web/app/about/page.tsx", self._info("About", f"{brand} is a connected competitive gaming platform generated by Autarch AI.", [("Our product", "One player identity across games, leaderboards and multiplayer rooms."), ("Our direction", "Build transparent, secure and entertaining online experiences.")]))
        self._write(root, "apps/web/app/privacy/page.tsx", self._info("Privacy", "A clear overview of how account and gameplay data is handled.", [("Account data", "Authentication and player profiles are stored in Supabase."), ("Payments", "Payment credentials are handled by the payment provider, not stored in the browser."), ("Your control", "Users should be able to review and delete their account data.")]))
        self._write(root, "apps/web/app/terms/page.tsx", self._info("Terms", "Rules for responsible use of the gaming platform.", [("Accounts", "Users are responsible for protecting their credentials."), ("Fair play", "Cheating, harassment and unauthorized access are prohibited."), ("Subscriptions", "Prices, renewal and cancellation terms must be shown before purchase.")]))
        self._write(root, "apps/web/lib/gameCatalog.ts", self._game_catalog())
        self._write(root, "apps/web/app/games/[slug]/page.tsx", self._game_preview())
        self._write(root, "apps/web/app/games/page.tsx", self._games_page())
        self._write(root, "apps/web/app/page.tsx", self._landing(brand))
        self._append_css(root)

    def audit(self, root: Path, request: str = ""):
        errors = []
        warnings = []
        for route, relative in self.REQUIRED_ROUTES.items():
            if not (root / relative).exists():
                errors.append(f"missing route {route}: {relative}")

        layout = self._read(root / "apps/web/app/layout.tsx")
        for required in ("AuthNav", "/help", "/contact", "/privacy", "/terms"):
            if required not in layout:
                errors.append(f"layout missing {required}")

        combined = "\n".join(
            self._read(path) for path in (root / "apps/web/app").rglob("*.tsx")
        )
        for href in re.findall(r'href=[{]?(["\'])(/[^"\']+)\1', combined):
            route = href[1].split("?")[0]
            if "${" in route or route.startswith("/games/"):
                continue
            if route not in self.REQUIRED_ROUTES:
                warnings.append(f"link target not covered by route audit: {route}")

        css = self._read(root / "apps/web/app/globals.css")
        if "@keyframes" not in css:
            errors.append("design missing animations")
        if ":hover" not in css or "scale(" not in css:
            errors.append("design missing interactive zoom treatment")
        if "image:" not in combined.lower() and "<img" not in combined and "backgroundimage" not in combined:
            errors.append("game experience missing imagery")
        requested_count = self._requested_game_count(request)
        catalog = self._read(root / "apps/web/lib/gameCatalog.ts")
        actual_count = catalog.count("slug:")
        if requested_count and actual_count < requested_count:
            errors.append(f"requested at least {requested_count} games, generated {actual_count}")
        if not (root / "apps/web/app/games/[slug]/page.tsx").exists():
            errors.append("missing playable game preview route")
        if 'href={`/games/${' not in combined:
            errors.append("game cards do not link to previews")
        if "create table" not in self._read(root / "supabase/schema.sql").lower():
            errors.append("database schema missing")
        return {"errors": errors, "warnings": sorted(set(warnings))}

    def _requested_game_count(self, request: str):
        match = re.search(r"(?:at least|minimum(?: of)?)\s+(\d+)\s+games?", request, re.I)
        return int(match.group(1)) if match else 0

