  {slug:"void-racers",title:"Void Racers",genre:"Space racing",description:"Race anti-gravity craft across collapsing star lanes.",image:"https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=1200&q=80"},
  {slug:"kingdom-siege",title:"Kingdom Siege",genre:"Strategy",description:"Build alliances and command massive fantasy battles.",image:"https://images.unsplash.com/photo-1518709268805-4e9042af9f23?auto=format&fit=crop&w=1200&q=80"},
